generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentTypeLabel 
       (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue) 
       (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct) 
       (SUM(xsd:decimal(?dividends)) AS ?totalDividends)
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?invType ;
           wm:currentValue ?currentValue ;
           wm:returnsPct ?returnsPct ;
           wm:dividends ?dividends .
  ?invType rdfs:label ?investmentTypeLabel .
}
GROUP BY ?investmentTypeLabel

